<script setup>
import {Head,Link,router} from '@inertiajs/vue3';import {art,modes,date} from '../art';
defineProps({catalog:Object,stats:Object,assignments:Array});
const menu=[['Fresh Catch 10','New questions and missed answers, ten at a time.','temaki','/practice?mode=fresh'],['Maki Mentor','Check your answer and learn as you go.','maki','/practice?mode=tutor'],['Wasabi Rush','A timed round with feedback at the finish.','wasabi','/practice?mode=exam'],['Memory Maki','Rate your confidence. Memo brings back what needs practice.','memo','/flashcards'],['Bento Builder','Make exam papers, answer sheets, and matching keys.','chef','/exams'],['Roll Call','Explore every subject, explanation, and bookmark.','logo','/library']];
</script><template><Head title="The Counter"/><section class="hero"><div><p class="eyebrow">Welcome to the counter</p><h1>Your next study round.</h1><p>{{catalog.total.toLocaleString()}} questions across four clinical subjects. Choose how you want to learn today.</p></div><img :src="art.banner" alt="SUSHI study crew"></section>
<div class="stat-grid"><div class="stat"><strong>{{stats.completed}}</strong><span>MCQs completed</span></div><div class="stat"><strong>{{stats.first_total?Math.round(stats.first_correct/stats.first_total*100)+'%':'None yet'}}</strong><span>First-attempt accuracy · n={{stats.first_total}}</span></div><div class="stat"><strong>{{stats.flashcards_due}}</strong><span>Low-confidence cards</span></div></div>
<div class="menu-grid"><Link v-for="[name,description,image,url] in menu" :key="name" :href="url" class="menu-card"><img :src="art[image]" :alt="name==='Memory Maki'?'Memo Maki':name"><div><h2>{{name}}</h2><p>{{description}}</p><span class="go">Let's roll →</span></div></Link></div>
<section v-if="stats.attempts.some(a=>a.status==='active')" class="panel"><h2>Pick up where you left off</h2><div v-for="a in stats.attempts.filter(a=>a.status==='active')" class="row"><span>{{modes[a.mode]}} · {{a.items_count}} questions</span><Link :href="'/attempts/'+a.id" class="button">Resume</Link></div></section>
<section v-if="assignments.length" class="panel"><h2>Your assigned bentos</h2><div v-for="a in assignments" :key="a.id" class="row"><div><strong>{{a.exam.title}}</strong><p>{{date(a.opens_at)}} to {{date(a.closes_at)}} · {{a.minutes}} minutes · {{a.max_attempts}} attempt(s)</p></div><button @click="router.post('/assignments/'+a.id+'/start')">Start exam</button></div></section>
<p class="muted"><Link href="/import">Import progress from the offline SUSHI app</Link> · <Link href="/password">Change your password</Link></p>
</template>
